/**
 * @method
 * @name searchTab1
 * @description 최종호가수익률 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchTab1 = async function() {
    if (edt_FromDd1.getValue() === '') {
        await $c.win.alert("[기준일자]를 입력하십시오.");
        edt_FromDd1.focus();
        return false;
    }
    let param = '';
    param += "&{P}V_STRT_DD=" + edt_FromDd1.getValue(); // 기준일

    let dsNm = 'BNS_LST_ORD_YD_RCV_LIST';
    let qryId = 'lds.stf.bnsdecl_mgr.select.selectBndLstOrdYdRcvList';
    $c.bns.fn_SearchBns("ULDBNS24200.xml", dts_List1, dsNm, qryId, param);
};

